// base64: 6 MiB of generated bytes encoded as base64 (RFC 4648, standard
// alphabet) and decoded again. Prints the encoded length, the sum of its
// character codes and 1 when the decoded bytes equal the original.
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static const char A[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

int main(void) {
    const int64_t n = 6 * 1024 * 1024, m = n / 3 * 4;
    uint8_t *data = malloc(n), *enc = malloc(m), *dec = malloc(n);
    for (int64_t i = 0; i < n; i++) data[i] = (uint8_t)((i * 2654435761LL >> 13) & 255);
    for (int64_t g = 0, k = 0; g < n; g += 3, k += 4) {
        uint32_t bits = (uint32_t)data[g] << 16 | (uint32_t)data[g + 1] << 8 | data[g + 2];
        enc[k] = A[bits >> 18 & 63];
        enc[k + 1] = A[bits >> 12 & 63];
        enc[k + 2] = A[bits >> 6 & 63];
        enc[k + 3] = A[bits & 63];
    }
    uint8_t value[256] = {0};
    for (int c = 0; c < 64; c++) value[(uint8_t)A[c]] = (uint8_t)c;
    for (int64_t q = 0, i = 0; q < m; q += 4, i += 3) {
        uint32_t bits = (uint32_t)value[enc[q]] << 18 | (uint32_t)value[enc[q + 1]] << 12 | (uint32_t)value[enc[q + 2]] << 6 | value[enc[q + 3]];
        dec[i] = (uint8_t)(bits >> 16);
        dec[i + 1] = (uint8_t)(bits >> 8);
        dec[i + 2] = (uint8_t)bits;
    }
    int64_t sum = 0;
    for (int64_t k = 0; k < m; k++) sum += enc[k];
    printf("%lld %lld %d\n", (long long)m, (long long)sum, memcmp(dec, data, n) == 0);
    free(data);
    free(enc);
    free(dec);
    return 0;
}
